// Arduino GPIO example
const int LED_PIN = 13;
const int BTN_PIN = 2;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  pinMode(BTN_PIN, INPUT_PULLUP); // internal pull-up resistor
}

void loop() {
  // LOW when button pressed (pull-up inverts logic)
  if (digitalRead(BTN_PIN) == LOW) {
    digitalWrite(LED_PIN, HIGH);
  } else {
    digitalWrite(LED_PIN, LOW);
  }
}

// Read analog sensor (potentiometer on A0)
int raw = analogRead(A0);         // 0-1023
float voltage = raw * (5.0 / 1023.0); // convert to volts
Serial.println(voltage);
